func bindChatRequest(r *http.Request) (ChatRequest, error) {
	var out ChatRequest
	queryVals := httpbind.Queries(r)
	needMessage := true
	if qv, ok := httpbind.QueryLookup(queryVals, "message"); ok {
		needMessage = false
		out.Message = qv
	}
	if needMessage {
		if httpbind.IsJSONRequest(r) {
			data, err := httpbind.ReadJSONBody(r)
			if err != nil {
				return out, err
			}
			if !jsonbind.IsBlank(data) {
				var bodyParser jsonbind.Parser
				bodyParser.Reset(data)
				p := &bodyParser
				null, err := p.ObjectStart()
				if err != nil {
					return out, httpbind.JSONBodyError(err)
				}
				if null {
					return out, httpbind.JSONBodyNotObject()
				}
				for n := 0; ; n++ {
					var rest []byte
					if p.KeyFast(n) {
						rest = p.Rest()
					} else {
						var ok bool
						var err error
						rest, ok, err = p.ObjectKeyRest(n)
						if err != nil {
							return out, httpbind.JSONBodyError(err)
						}
						if !ok {
							break
						}
					}
					idx, k := -1, 0
					if len(rest) >= 9 && string(rest[:9]) == "\"message\"" {
						idx, k = 0, 9
					}
					if idx >= 0 {
						p.Skip(k)
						if !p.ColonFast() {
							if err := p.Colon(); err != nil {
								return out, httpbind.JSONBodyError(err)
							}
						}
					} else {
						key, err := p.ObjectKeyName()
						if err != nil {
							return out, httpbind.JSONBodyError(err)
						}
						switch string(key) {
						case "message":
							idx = 0
						default:
							if err := p.SkipValue(); err != nil {
								return out, httpbind.JSONBodyError(err)
							}
							continue
						}
					}
					switch idx {
					case 0:
						if !needMessage {
							if err := p.SkipValue(); err != nil {
								return out, httpbind.JSONBodyError(err)
							}
							continue
						}
						v, err := p.String()
						if err != nil {
							return out, jsonbind.FieldError("message", "invalid string", err)
						}
						out.Message = v
					}
				}
				p.Release()
				if err := p.End(); err != nil {
					return out, httpbind.JSONBodyError(err)
				}
			}
		} else {
			formBody, _, err := httpbind.ReadFormBody(r, true, false)
			if err != nil {
				return out, err
			}
			if needMessage && formBody.Present() {
				if fv, ok := httpbind.FormLookup(formBody, "message"); ok {
					out.Message = fv
				}
			}
		}
	}
	return out, nil
}

